require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$items=loadCandidateRecords();$pdo=db();$byJob=[];$bySource=[];$missingSkills=[];$gapCount=0;$missing=['email'=>0,'country'=>0,'phone'=>0,'experience'=>0];$emails=[];foreach($items as $c){$job=$c['role']??'Unassigned';$byJob[$job]['scores'][]=(int)$c['score'];$source=$c['source']??'Unknown';$bySource[$source]['total']=($bySource[$source]['total']??0)+1;if(in_array($c['stage']??'', ['Interview','Offer'],true))$bySource[$source]['converted']=($bySource[$source]['converted']??0)+1;foreach($c['analysis']['missing_keywords']??[] as $skill)$missingSkills[$skill]=($missingSkills[$skill]??0)+1;if(!empty($c['experience']['gaps']))$gapCount++;if(empty($c['email']))$missing['email']++;if(empty($c['phone']))$missing['phone']++;if(empty($c['experience']['total_months']))$missing['experience']++;if(!empty($c['email']))$emails[strtolower($c['email'])]=($emails[strtolower($c['email'])]??0)+1;}$missing['country']=(int)$pdo->query("SELECT COUNT(*) FROM candidates WHERE country_code IS NULL OR country_code=''")->fetchColumn();$duplicates=array_sum(array_map(fn($n)=>max(0,$n-1),$emails));arsort($missingSkills);$mail=$pdo->query('SELECT status,COUNT(*) total FROM email_recipients GROUP BY status')->fetchAll();$activePage='dashboard';$pageTitle='Analytics · ResumeIQ';$pageStyles='<style>.analytics-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:10px}.analytics-panel{padding:17px}.analytics-panel h2{font-size:13px;margin:0 0 13px}.data-row{display:grid;grid-template-columns:150px 1fr 60px;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid var(--line);font-size:9px}.track{height:7px;background:#eeeef5;border-radius:4px;overflow:hidden}.track i{height:100%;display:block;background:var(--primary)}.quality-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.quality-card{padding:11px;border:1px solid var(--line);border-radius:8px}.quality-card strong{display:block;font-size:18px}.quality-card span{font-size:8px;color:var(--muted)}.unavailable{padding:13px;background:#fafafe;border:1px dashed var(--line);border-radius:8px;color:var(--muted);font-size:9px}@media(max-width:760px){.analytics-grid{grid-template-columns:1fr}.quality-grid{grid-template-columns:repeat(2,1fr)}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-chart-line"></i> Hiring intelligence</div><h1>Analytics</h1><p>Real operational data only. Unavailable metrics stay marked until event history exists.</p></div><a class="btn" href="dashboard.php">Dashboard</a></section><section class="analytics-grid"><article class="panel analytics-panel"><h2>Website vs upload vs Drive conversion</h2><?php foreach($bySource as $source=>$x):$rate=$x['total']?round(($x['converted']??0)/$x['total']*100):0;?><div class="data-row"><span><?=htmlspecialchars($source)?></span><div class="track"><i style="width:<?=$rate?>%"></i></div><b><?=$rate?>%</b></div><?php endforeach?></article><article class="panel analytics-panel"><h2>Average ATS score by job</h2><?php foreach($byJob as $job=>$x):$avg=round(array_sum($x['scores'])/count($x['scores']));?><div class="data-row"><span><?=htmlspecialchars($job)?></span><div class="track"><i style="width:<?=$avg?>%"></i></div><b><?=$avg?>%</b></div><?php endforeach?></article><article class="panel analytics-panel"><h2>Skill shortage chart</h2><?php $max=max(1,...array_values($missingSkills?:[1]));foreach(array_slice($missingSkills,0,10,true) as $skill=>$count):?><div class="data-row"><span><?=htmlspecialchars($skill)?></span><div class="track"><i style="width:<?=round($count/$max*100)?>%"></i></div><b><?=$count?></b></div><?php endforeach?><?php if(!$missingSkills):?><div class="unavailable">Re-scan candidates to persist missing-skill evidence.</div><?php endif?></article><article class="panel analytics-panel"><h2>Employment, duplicates and data quality</h2><div class="quality-grid"><div class="quality-card"><strong><?=$gapCount?></strong><span>Employment gaps</span></div><div class="quality-card"><strong><?=$duplicates?></strong><span>Duplicate emails</span></div><?php foreach($missing as $key=>$count):?><div class="quality-card"><strong><?=$count?></strong><span>Missing <?=htmlspecialchars($key)?></span></div><?php endforeach?></div></article><article class="panel analytics-panel"><h2>Email delivery / failure report</h2><?php foreach($mail as $row):?><div class="data-row"><span><?=htmlspecialchars(ucfirst($row['status']))?></span><div></div><b><?=$row['total']?></b></div><?php endforeach?><?php if(!$mail):?><div class="unavailable">No email events yet. Preview batches are available from Wishlist.</div><?php endif?></article><article class="panel analytics-panel"><h2>Timeline and interviews</h2><div class="unavailable">Average pipeline time, confirmation/reschedule rate, recruiter activity and upcoming interviews require their append-only event tables. No values are fabricated.</div></article></section>
